WITH parsed AS (SELECT id, service, level, latency_ms, status_code, payload_json, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, ARRAY_CONTAINS(MAP_KEYS(context), 'region') AS has_region, context['version'] AS version, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count FROM app_logs WHERE level IN ('INFO', 'DEBUG')) SELECT CASE WHEN latency_ms >= 2289 THEN 'PREMIUM' ELSE 'STANDARD' END AS latency_ms_tier, COUNT(DISTINCT id) AS distinct_ids, SIZE(COLLECT_SET(level)) AS num_levels, COUNT(*) AS event_count FROM parsed GROUP BY CASE WHEN latency_ms >= 2289 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING COUNT(*) < 1000 ORDER BY event_count ASC;
